/**
 * Slug utilities for project naming
 *
 * @module cli/shared/slug
 */
export function randomSuffix(len = 6) {
    const chars = "abcdefghijklmnopqrstuvwxyz0123456789";
    return Array.from({ length: len }, () => chars[Math.floor(Math.random() * chars.length)]).join("");
}
export function normalizeProjectSlug(value) {
    const withoutScope = value.replace(/^@[^/]+\//, "");
    const slug = withoutScope
        .trim()
        .toLowerCase()
        .replace(/[^a-z0-9-]+/g, "-")
        .replace(/^-+|(?<!-)-+$/g, "")
        .replace(/-+/g, "-");
    return slug || "my-app";
}
